package main

import (
	"io"
	"os"
	"os/exec"
)

func main() {
	io.ReadAll(os.Stdin)
	cmd := exec.Command("sleep", "30")
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
