package daemon

import (
	"context"
	"errors"
	"os/exec"
	"strings"
	"testing"
	"time"
)

func TestProbeWaitDelayErrorClassification(t *testing.T) {
	cfg := MCPServerConfig{Command: "/tmp/mcp-probe-bin/forksleep", Args: []string{}}
	args := append(append([]string{}, cfg.Args...), "--help")
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	cmd := exec.CommandContext(ctx, cfg.Command, args...)
	cmd.WaitDelay = time.Second
	out, err := cmd.CombinedOutput()
	t.Logf("ctx.Err()=%v err=%v", ctx.Err(), err)
	if ctx.Err() != nil {
		t.Fatal("did not expect ctx.Err() to be set -- WaitDelay fires independently")
	}
	if err != nil {
		if exitErr, ok := errors.AsType[*exec.ExitError](err); ok {
			t.Logf("would hit the *exec.ExitError branch: exitcode=%d, out=%q", exitErr.ExitCode(), out)
			return
		}
		t.Logf("would hit the generic error branch (not an *exec.ExitError): %v, out=%q", err, out)
		if !strings.Contains(err.Error(), "WaitDelay") {
			t.Fatal("expected the generic error to mention WaitDelay")
		}
		return
	}
	t.Fatal("expected a non-nil error")
}
EOF
