// Scratch eval: a Command containing a slash is resolved by exec.LookPath
// RELATIVE TO CWD, not PATH -- Go's documented behavior matches historical
// Unix PATH search semantics (a name with a "/" is never looked up in PATH).
func TestDJBEval_SlashInCommand_RelativeToCWD(t *testing.T) {
	cwd, err := os.Getwd()
	require.NoError(t, err)
	t.Cleanup(func() { _ = os.Chdir(cwd) })

	workDir := t.TempDir()
	require.NoError(t, os.Chdir(workDir))

