	}
	tmpl := &MissionTemplate{TmpDir: t.TempDir()}
	path, err := tmpl.BuildMCPConfig([]string{"rel"}, registry)
	require.NoError(t, err, "LookPath resolves a slash-containing name relative to CWD, not PATH -- this is expected to succeed even with an unrelated/empty PATH")
	defer os.Remove(path)

	data, readErr := os.ReadFile(path)
	require.NoError(t, readErr)
	t.Logf("config: %s", data)
}
